/* Read-only system information. No raw device opens, commands or persistence. */
#include "device_info_data.h"
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <limits.h>
extern int hb_info_scanf(const char *,const char *,...) __asm__("sscanf");
static char input[32769];
static void copy(char *out,const char *in,unsigned size){if(!size)return;unsigned i=0;while(i+1<size&&in[i]&&in[i]!='\n'&&in[i]!='\r'){unsigned c=(unsigned char)in[i];out[i]=(char)(c>=32&&c<127?c:'?');i++;}out[i]=0;}
static void decimal(char*out,unsigned long long n){char b[21];unsigned i=0;do{b[i++]=(char)('0'+n%10);n/=10;}while(n);unsigned j=0;while(i)out[j++]=b[--i];out[j]=0;}
void hb_info_size(char*out,unsigned long long n){static const char*units[]={"B","KiB","MiB","GiB","TiB"};unsigned unit=0;unsigned long long divisor=1;while(unit<4&&n/divisor>=1024){divisor*=1024;unit++;}char whole[24],fraction[4];decimal(whole,n/divisor);if(!unit){snprintf(out,38,"%s B",whole);return;}decimal(fraction,((n%divisor)*10)/divisor);snprintf(out,38,"%s.%s %s",whole,fraction,units[unit]);}
static struct hb_info_page*page(struct hb_device_info*d,const char*title){if(d->count>=HB_INFO_MAX_PAGES)return 0;struct hb_info_page*p=&d->pages[d->count++];memset(p,0,sizeof *p);copy(p->title,title,sizeof p->title);return p;}
static void line(struct hb_info_page*p,const char*s){if(p&&p->count<HB_INFO_ROWS)copy(p->lines[p->count++],s,HB_INFO_COLS);}
static void field(struct hb_info_page*p,const char*key,const char*value){if(!p)return;char b[256];snprintf(b,sizeof b,"%s: %s",key,value&&*value?value:"Unavailable");if(strlen(b)<HB_INFO_COLS){line(p,b);return;}line(p,key);const char*s=value;while(*s&&p->count<HB_INFO_ROWS){char piece[HB_INFO_COLS];copy(piece,s,sizeof piece);line(p,piece);unsigned n=(unsigned)strlen(piece);if(!n)break;s+=n;}}
static int read_text(const char*root,const char*name){char path[512];input[0]=0;if(snprintf(path,sizeof path,"%s%s",root?root:"",name)>=(int)sizeof path)return -1;FILE*f=fopen(path,"rb");if(!f)return -1;size_t used=fread(input,1,sizeof input-1,f);int bad=ferror(f);if(used==sizeof input-1){int c=fgetc(f);if(c!=EOF)bad=1;}if(fclose(f))bad=1;input[used]=0;return bad?-1:0;}
static int value(const char*key,char*out,unsigned capacity){const char*s=input;size_t n=strlen(key);while(*s){const char*end=strchr(s,'\n');if(!end)end=s+strlen(s);const char*colon=memchr(s,':',(size_t)(end-s));if(colon){const char*k=colon;while(k>s&&(k[-1]==' '||k[-1]=='\t'))k--;if((size_t)(k-s)==n&&!strncmp(s,key,n)){const char*v=colon+1;while(v<end&&(*v==' '||*v=='\t'))v++;copy(out,v,capacity);return 0;}}s=*end?end+1:end;}out[0]=0;return -1;}
static int memory_value(const char*name,unsigned long long*out){char b[96];if(value(name,b,sizeof b))return -1;char*end;unsigned long long n=strtoull(b,&end,10);if(end==b)return -1;while(*end==' '||*end=='\t')end++;if(strcmp(end,"kB")||n>~0ULL/1024)return -1;*out=n*1024;return 0;}
static void memory_field(struct hb_info_page*p,const char*key,const char*label){unsigned long long n;char b[38];if(memory_value(key,&n))field(p,label,"Unavailable");else{hb_info_size(b,n);field(p,label,b);}}
static void first_file(struct hb_info_page*p,const char*root,const char*path,const char*label){if(read_text(root,path))field(p,label,"Unavailable");else field(p,label,input);}
static int decode_path(const char*s,char*out,unsigned capacity){unsigned i=0;for(unsigned j=0;s[j];j++){unsigned c=(unsigned char)s[j];if(c=='\\'){if(s[j+1]<'0'||s[j+1]>'7'||s[j+2]<'0'||s[j+2]>'7'||s[j+3]<'0'||s[j+3]>'7')return -1;c=(unsigned)(s[j+1]-'0')*64+(unsigned)(s[j+2]-'0')*8+(unsigned)(s[j+3]-'0');j+=3;}if(!c||i+1>=capacity)return -1;out[i++]=(char)c;}out[i]=0;return 0;}
static int virtual_fs(const char*s){const char*names[]={"proc","sysfs","devpts","usbfs","securityfs","debugfs","configfs","cgroup","cgroup2",0};for(unsigned i=0;names[i];i++)if(!strcmp(s,names[i]))return 1;return 0;}
static int readonly(const char*options){const char*p=options;while(*p){const char*e=strchr(p,',');if(!e)e=p+strlen(p);if(e-p==2&&!strncmp(p,"ro",2))return 1;p=*e?e+1:e;}return 0;}
static void mounts(struct hb_device_info*d,const char*root,hb_info_space_fn space){if(read_text(root,"/proc/mounts")){line(page(d,"FILESYSTEMS"),"Mount table unavailable");return;}char saved[sizeof input];memcpy(saved,input,sizeof saved);char*s=saved;unsigned count=0;while(*s&&count<32){char*end=strchr(s,'\n');if(end)*end=0;char dev[256],mount[256],type[64],options[256],path[256];if(hb_info_scanf(s,"%255s %255s %63s %255s",dev,mount,type,options)==4&&!decode_path(mount,path,sizeof path)){struct hb_info_page*p=page(d,"FILESYSTEM");if(!p)break;count++;field(p,"Mount",path);field(p,"Device",dev);field(p,"Type",type);field(p,"Mode",readonly(options)?"Read only":"Read write");if(virtual_fs(type)){line(p,"Virtual filesystem");line(p,"Not a storage partition");}else if(!space){line(p,"Capacity: unavailable");if(root&&*root)line(p,"Fixture - no host disk query");}else{struct hb_info_space n;if(space(path,&n)||n.free>n.total||n.available>n.free){line(p,"Capacity: unavailable");}else{char b[38];hb_info_size(b,n.total);field(p,"Total",b);hb_info_size(b,n.total-n.free);field(p,"Used",b);hb_info_size(b,n.free);field(p,"Free",b);hb_info_size(b,n.available);field(p,"Available",b);line(p,"Free includes reserved blocks");if(!strcmp(type,"tmpfs")||!strcmp(type,"ramfs"))line(p,"RAM filesystem - not flash");}}}if(!end)break;s=end+1;}if(*s&&count==32)line(page(d,"FILESYSTEM LIMIT"),"More than 32 mount entries");}
static void flash(struct hb_device_info*d,const char*root){struct hb_info_page*p=page(d,"FLASH PARTITIONS");if(read_text(root,"/proc/mtd")){line(p,"MTD table unavailable");return;}char saved[sizeof input];memcpy(saved,input,sizeof saved);char*s=saved;while(*s){char*end=strchr(s,'\n');if(end)*end=0;unsigned id;unsigned long long bytes,erase;char name[128];if(hb_info_scanf(s,"mtd%u: %llx %llx \"%127[^\"]\"",&id,&bytes,&erase,name)==4){if(p->count+3>HB_INFO_ROWS)p=page(d,"FLASH PARTITIONS");if(!p)break;char label[160],n[38];snprintf(label,sizeof label,"MTD %u %s",id,name);line(p,label);hb_info_size(n,bytes);field(p,"Size",n);hb_info_size(n,erase);field(p,"Erase block",n);}if(!end)break;s=end+1;}line(p,"MTD size is physical capacity");line(p,"Unmapped free space is unknown");}
int hb_info_collect(struct hb_device_info*d,const char*root,hb_info_space_fn space){if(!d)return -1;memset(d,0,sizeof *d);d->fixture=root&&*root;struct hb_info_page*p=page(d,"OVERVIEW");line(p,d->fixture?"PC TEST DATA":"Live read-only information");first_file(p,root,"/proc/sys/kernel/osrelease","Kernel");line(p,"CPU and RAM from Linux /proc");line(p,"Storage from mount statistics");line(p,"Binary units: 1024 bytes per KiB");line(p,"No storage or settings writes");p=page(d,"CPU");if(read_text(root,"/proc/cpuinfo"))line(p,"CPU information unavailable");else{const char*keys[]={"Processor","model name","Hardware","Revision","CPU architecture","CPU implementer","CPU part","Features","BogoMIPS",0};for(unsigned i=0;keys[i];i++){char b[256];if(!value(keys[i],b,sizeof b))field(p,keys[i],b);}}p=page(d,"MEMORY");if(read_text(root,"/proc/meminfo"))line(p,"Memory information unavailable");else{memory_field(p,"MemTotal","OS visible RAM");memory_field(p,"MemFree","Free RAM");memory_field(p,"MemAvailable","Available RAM");memory_field(p,"Buffers","Buffers");memory_field(p,"Cached","Cached");memory_field(p,"SwapTotal","Swap total");memory_field(p,"SwapFree","Swap free");line(p,"Installed RAM may exceed OS RAM");line(p,"Unavailable means not reported");}p=page(d,"SYSTEM");first_file(p,root,"/proc/sys/kernel/ostype","OS");first_file(p,root,"/proc/sys/kernel/osrelease","Kernel");first_file(p,root,"/proc/version","Build");first_file(p,root,"/usr/local/share/genesys/GENESYS_VERSION","Sony system build");p=page(d,"UPTIME");first_file(p,root,"/proc/uptime","Uptime and idle seconds");line(p,"First number is uptime seconds");line(p,"Second is cumulative idle time");mounts(d,root,space);flash(d,root);return 0;}
